function publication(s,id){
 const common='11월 7일 책방에서 반환한 작은 상자는 이수진 씨의 개인 물건입니다. 이를 기증품 반출처럼 적고 이름을 공개한 책임은 윤서경에게 있습니다.';
 const own=s.flags.signed?'저 윤도하는 의견 칸을 뺀 표를 만들었고, 찬성 명단으로 쓰일 수 있다는 경고를 듣고도 전달을 멈추지 않았습니다.':'윤도하가 출석 명단 정리에 참여한 사실을 확인했습니다. 당시 전달 경위는 추가 확인이 필요합니다.';
 const witnesses=[s.flags.sujinWitness?'이수진 · 원본 작성과 당시 이의 제기':null,s.flags.taeoWitness==='named'?'박태오 · 서류 전달 범위':null].filter(Boolean);
 const variants={
 joint:{heading:'모서리책방 기록 정정과 당사자 진술',body:[common,'2024년 독서모임 출석 23명이 전원 지지로 바뀐 자료가 전달됐습니다. 원본에는 반대·보류 여섯 명의 의견이 있습니다.',own,'윤서경은 잘못된 제출본을 확인하고도 새 공간 운영 논의가 끊길 것을 염려해 정정을 미뤘습니다. 두 사람은 각자의 이름으로 이 경위를 남깁니다.','월요일 설명회 명단의 재사용 중단과 당사자 의견의 정정을 요구합니다.'],attachments:['attendance','supporters','fileVersions','accountDraft'],people:['윤도하','윤서경',...witnesses],cost:'도하의 작업 이력과 경고를 들은 대화가 본인 이름으로 남습니다. 서경도 정정 보류를 인정합니다. 명단 정정 요청의 수용과 두 사람의 일·관계 회복은 아직 정해지지 않았습니다.'},
 limited:{heading:'출석과 지지는 서로 다른 기록이었다',body:[common,'원본과 주민 당사자 확인에서 반대·보류 의견이 지지로 반영된 사실을 확인했습니다. 김정희 씨와 최은숙 씨는 자신들이 밝힌 의견으로 바로잡아 달라고 요청했습니다.',own,'동의한 인터뷰와 필요한 행의 발췌 자료를 공개합니다. 자료가 바뀐 전체 경위는 후속 취재에서 확인합니다.'],attachments:['attendance','supporters'],people:['강나래 · 취재',...witnesses],cost:'이름과 생활 사정의 노출을 줄입니다. 자료를 바꾼 전체 경위는 후속 확인이 남아, 설명회 이전의 완전한 정정은 장담할 수 없습니다.'},
 full:{heading:'출석부 원본과 전달 기록을 공개합니다',body:[common,'출석·의견지 전체, 제출본, 중간 정리본과 당시 작업 대화를 함께 공개합니다. 누구의 의견이 어떤 과정에서 사라졌는지 확인할 수 있습니다.','윤도하는 의견 칸을 제외했고, 그 용도에 대한 경고를 전달받고도 정리본 전달을 진행했습니다. 윤서경은 제출본의 문제를 알고도 정정을 미뤘습니다.','이수진 씨는 전체 사본의 공개에 반대했습니다. 사본에는 주민 스물세 사람의 이름·연락처와 당시 사정이 함께 들어 있습니다.'],attachments:['raw','supporters','fileVersions','workMessages'],people:['윤도하 · 게시','윤서경 · 기록에 등장','주민 23명 · 원본에 포함'],cost:'전체 사본은 수진이 공개에 반대한 자료입니다. 그 안의 연락처와 생활 사정까지 함께 노출됩니다. 도하가 당시 경고를 들은 내용도 작업 대화에서 드러납니다.'},
 private:{heading:'당사자별 정정 요청과 48시간 유예',body:[common,'원본 발췌와 당사자 의견을 설명회 담당 창구에 개별 전달합니다. 수진과 주민들에게 각자에게 해당하는 기록을 돌려보냅니다.','강나래 기자에게 공개 보도를 48시간 미뤄 달라고 요청합니다. 이후 보도 여부는 기자의 추가 확인에 따릅니다.',own,'현재 공개된 지지자료의 경위까지 설명하는 공개문은 오늘 올리지 않습니다.'],attachments:['attendance','supporters'],people:['담당 창구와 해당 당사자에게 전달'],cost:'가족과 주변 사람들의 당장 공개되는 부담은 줄어듭니다. 월요일 설명회 전까지 잘못된 자료가 충분히 수정되지 않을 수 있고, 수진과 주민들이 각자 다시 설명해야 할 일이 남습니다.'}
 };
 return variants[id];
}
